const mine=routes.filter((_,i)=>i%SHARDS===SHARD), sleep=ms=>new Promise(r=>setTimeout(r,ms));
const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function u(route){const x=new URL(route,BASE);x.searchParams.set('preview_theme_id',THEME);return x.toString()}
async function nav(p,url){let last;for(let i=0;i<5;i++){try{const r=await p.goto(url,{waitUntil:'domcontentloaded',timeout:90000});if(r?.status()===200){if(url.includes('/collections/'))await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000}).catch(()=>{});await sleep(600);return r}last=new Error('HTTP '+(r?.status()||0))}catch(e){last=e}await sleep(2000*(i+1))}throw last||new Error('navigation failed')}
async function snapshot(p){return p.evaluate(()=>{const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2};const main=document.querySelector('#MainContent'),side=[...document.querySelectorAll('#MainContent .sq-refine-v3-sidebar')].find(vis);const groups=side?[...side.querySelectorAll(':scope>details.sq-refine-v3-group')].map((d,gi)=>({gi,title:(d.querySelector(':scope>summary')?.textContent||'').replace(/\s+/g,' ').trim(),items:[...d.querySelectorAll('input[type=checkbox][data-kind]')].map((x,ii)=>({ii,kind:x.dataset.kind||'',target:x.dataset.target||'',name:x.dataset.filterName||'',value:x.dataset.filterValue||'',label:(x.closest('label')?.innerText||'').replace(/\s+/g,' ').trim(),checked:x.checked}))})):[];const grid=[...document.querySelectorAll('#MainContent .sq-refine-v3-results .product-grid')].find(vis),cards=grid?[...grid.children].filter(x=>vis(x)&&x.querySelector('a[href*="/products/"]')):[];let row=0;if(cards.length){const y=cards[0].getBoundingClientRect().top;row=cards.filter(c=>Math.abs(c.getBoundingClientRect().top-y)<5).length}const legacy=[...document.querySelectorAll('#MainContent .sq-maker-browser,#MainContent .sq-global-refine-sidebar,#MainContent .facets-toggle__wrapper,#MainContent theme-drawer#filters-drawer,#MainContent [class*="button-tree"],#MainContent [class*="category-grid"],#MainContent [class*="type-grid"],#MainContent [class*="branch-grid"],#MainContent [class*="root-categories"]')].filter(e=>vis(e)&&!e.closest('.sq-refine-v3-sidebar,.sq-refine-v3-results')).length;const pageSizes=[...document.querySelectorAll('#MainContent .sq-refine-v3-page-size input')].map(x=>({value:x.value,checked:x.checked}));return{ready:main?.dataset.sqRefineV3Ready||'',error:main?.dataset.sqRefineV3Error||'',title:(side?.querySelector('.sq-refine-v3-sidebar__title')?.textContent||'').trim(),position:side?getComputedStyle(side).position:'',groups,cards:cards.length,row,legacy,overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+3,broken:[...document.images].filter(i=>i.complete&&i.naturalWidth===0).length,pageSizes,url:location.href};})}
function baseFailures(s,mode){const e=[];if(s.ready!=='true'||s.error)e.push('V3 not ready '+s.error);if(s.title.toUpperCase()!=='REFINE PRODUCTS')e.push('Refine header');if(!s.cards)e.push('no products');const expectedRow=Math.min(s.cards,mode==='desktop'?3:2);if(s.cards>0&&s.row!==expectedRow)e.push(`${mode} row ${s.row} expected ${expectedRow}`);if(mode==='desktop'&&s.position!=='sticky')e.push('desktop sticky '+s.position);if(mode==='mobile'&&s.position==='sticky')e.push('mobile unexpectedly sticky');if(s.legacy)e.push('legacy/native visible '+s.legacy);if(s.overflow)e.push('horizontal overflow');if(s.broken)e.push('broken images '+s.broken);if(s.pageSizes.map(x=>x.value).join(',')!=='50,100,250')e.push('page size controls');return e}
async function findInput(p,opt){return p.locator('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group').nth(opt.gi).locator('input[type=checkbox][data-kind]').nth(opt.ii)}
async function exerciseOptions(p,base,mode,pageErrors){const first=await snapshot(p),options=first.groups.flatMap(g=>g.items.map(i=>({...i,gi:g.gi,group:g.title}))),out=[];
 for(let n=0;n<options.length;n++){const opt=options[n];let rec={group:opt.group,label:opt.label,kind:opt.kind,pass:false,selected:false,reset:false,resultCards:null,error:''};try{await nav(p,base);const inp=await findInput(p,opt);if(await inp.count()!==1)throw new Error('input not found');const before=(await snapshot(p)).url;await Promise.all([p.waitForNavigation({waitUntil:'domcontentloaded',timeout:45000}).catch(()=>null),inp.click()]);await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000}).catch(()=>{});await sleep(500);let s=await snapshot(p);rec.resultCards=s.cards;const checked=s.groups.flatMap(g=>g.items).some(x=>x.checked&&((opt.kind==='native'&&x.name===opt.name&&x.value===opt.value)||(opt.kind==='structural'&&x.label===opt.label)));const changed=s.url!==before;rec.selected=checked&&changed; if(!rec.selected)throw new Error('selection did not become active'); if(baseFailures(s,mode).some(x=>!/no products/.test(x)))throw new Error('layout failure after select');const active=s.groups.flatMap(g=>g.items).find(x=>x.checked&&((opt.kind==='native'&&x.name===opt.name&&x.value===opt.value)||(opt.kind==='structural'&&x.label===opt.label)));if(!active)throw new Error('active checkbox not recoverable');const groups=s.groups;let ai=null;for(const g of groups){for(const x of g.items){if(x===active){ai={gi:g.gi,ii:x.ii};break}}if(ai)break}if(!ai)throw new Error('active index missing');const resetInp=p.locator('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group').nth(ai.gi).locator('input[type=checkbox][data-kind]').nth(ai.ii);await Promise.all([p.waitForNavigation({waitUntil:'domcontentloaded',timeout:45000}).catch(()=>null),resetInp.click()]);await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000}).catch(()=>{});await sleep(450);s=await snapshot(p);rec.reset=!s.groups.flatMap(g=>g.items).some(x=>x.checked);if(!rec.reset)throw new Error('reset left checkbox active');rec.pass=true;}catch(e){rec.error=String(e)}out.push(rec);if((n+1)%10===0)console.log(`${mode} option progress ${n+1}/${options.length}`)}
 return {count:options.length,passed:out.filter(x=>x.pass).length,failed:out.filter(x=>!x.pass).length,items:out,pageErrors:[...pageErrors]};}
async function exercisePageSizes(p,base,mode){const out=[];let lastCards=0;for(const value of ['50','100','250']){const rec={value,pass:false,cards:0,error:''};try{await nav(p,base);const input=p.locator(`#MainContent .sq-refine-v3-page-size input[value="${value}"]`);if(await input.count()!==1)throw new Error('control missing');if(value!=='50')await Promise.all([p.waitForNavigation({waitUntil:'domcontentloaded',timeout:60000}).catch(()=>null),input.click()]);await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000}).catch(()=>{});await sleep(600);const s=await snapshot(p);rec.cards=s.cards;const selected=s.pageSizes.find(x=>x.value===value)?.checked;if(!selected)throw new Error('control not selected');if(Number(value)===50&&s.cards>50)throw new Error('50 control rendered >50');if(Number(value)>50&&s.cards<lastCards)throw new Error('larger page size reduced card count');if(s.cards>Number(value))throw new Error('rendered more than requested');const errs=baseFailures(s,mode).filter(x=>!x.includes('row'));if(errs.length)throw new Error(errs.join('; '));rec.pass=true;lastCards=s.cards;}catch(e){rec.error=String(e)}out.push(rec)}return out}
async function device(route,mode,viewport){const browser=await chromium.launch({headless:true});const context=await browser.newContext({viewport,recordVideo:{dir:OUT,size:{width:mode==='desktop'?1280:390,height:720}}});const p=await context.newPage(),pageErrors=[];p.on('pageerror',e=>pageErrors.push(String(e)));const base=u(route);let initial=null,errors=[];try{await nav(p,base);initial=await snapshot(p);errors.push(...baseFailures(initial,mode));const labels=initial.groups.map(g=>g.title);if(!labels.some(x=>/Shop by Type/i.test(x)))errors.push('missing Shop by Type');if(!labels.some(x=>/Shop by Manufacturer/i.test(x)))errors.push('missing Shop by Manufacturer');if(route==='/collections/literature'){if(!labels.some(x=>/Author/i.test(x)))errors.push('missing Author');if(!labels.some(x=>/Publisher/i.test(x)))errors.push('missing Publisher');if(!labels.some(x=>/War|Conflict/i.test(x)))errors.push('missing War/Conflict');if(!labels.some(x=>/Branch/i.test(x)))errors.push('missing Branch')}if(route==='/collections/firearm-accessories'&&!labels.some(x=>/Firearm Make|Make \/ Model/i.test(x)))errors.push('missing Firearm Make/Model');if(route==='/collections/armed-forces-gear'&&!labels.some(x=>/Branch/i.test(x)))errors.push('missing Branch');}catch(e){errors.push(String(e))}
 const sizes=initial?await exercisePageSizes(p,base,mode):[];const interactions=initial?await exerciseOptions(p,base,mode,pageErrors):{count:0,passed:0,failed:0,items:[],pageErrors};if(interactions.failed)errors.push(`checkbox failures ${interactions.failed}/${interactions.count}`);if(pageErrors.length)errors.push('pageErrors '+JSON.stringify([...new Set(pageErrors)]));await nav(p,base).catch(()=>{});await p.screenshot({path:path.join(OUT,`${slug(route)}-${mode}.png`),fullPage:true}).catch(()=>{});const v=p.video();await p.close();await context.close();if(v){const src=await v.path().catch(()=>null);if(src)fs.copyFileSync(src,path.join(OUT,`${slug(route)}-${mode}.webm`))}await browser.close();return{mode,initial,pageSizes:sizes,interactions,pageErrors:[...new Set(pageErrors)],errors,pass:errors.length===0}}
async function legacy(name,route){const browser=await chromium.launch({headless:true});const p=await browser.newPage({viewport:{width:1440,height:1000}});let status=0,error='';try{const r=await nav(p,u(route));status=r.status()}catch(e){error=String(e)}const bad=await p.evaluate(()=>!!document.querySelector('.sq-refine-v3-sidebar,[data-sq-refine-v3-root]')).catch(()=>true);await p.screenshot({path:path.join(OUT,`${slug(route)}-desktop.png`),fullPage:true}).catch(()=>{});await browser.close();const errors=[];if(status!==200)errors.push('HTTP '+status);if(error)errors.push(error);if(bad)errors.push('unexpected V3 UI');return{name,route,type:'legacy',pass:!errors.length,errors}}
const report={theme:THEME,shard:SHARD,shards:SHARDS,stateGuardExcluded:true,routes:[],failures:[],interactionCount:0,interactionPassed:0};
for(const [name,route,type] of mine){console.log('START '+name);if(type==='legacy'){const x=await legacy(name,route);report.routes.push(x);if(!x.pass)report.failures.push(...x.errors.map(e=>name+': '+e));continue}const desktop=await device(route,'desktop',{width:1440,height:1000}),mobile=await device(route,'mobile',{width:390,height:844});report.interactionCount+=desktop.interactions.count+mobile.interactions.count;report.interactionPassed+=desktop.interactions.passed+mobile.interactions.passed;const errors=[...desktop.errors.map(e=>'desktop '+e),...mobile.errors.map(e=>'mobile '+e)];const row={name,route,type,desktop,mobile,errors,pass:!errors.length};report.routes.push(row);if(errors.length)report.failures.push(...errors.map(e=>name+': '+e));console.log(`${row.pass?'PASS':'FAIL'} ${name} interactions ${desktop.interactions.passed+mobile.interactions.passed}/${desktop.interactions.count+mobile.interactions.count}`)}
fs.writeFileSync(path.join(OUT,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({shard:SHARD,pass:report.routes.filter(r=>r.pass).length,fail:report.routes.filter(r=>!r.pass).length,interactionPassed:report.interactionPassed,interactionCount:report.interactionCount,failures:report.failures},null,2));if(report.failures.length||report.interactionPassed!==report.interactionCount)process.exit(2);
